def semver_sort(versions):
    def parse_key(v):
        # Split off build metadata (everything after first '+')
        plus_idx = v.find('+')
        if plus_idx != -1:
            core = v[:plus_idx]
        else:
            core = v

        # Split off pre-release (everything after first '-')
        dash_idx = core.find('-')
        if dash_idx != -1:
            main_part = core[:dash_idx]
            prerelease_part = core[dash_idx+1:]
            has_prerelease = True
        else:
            main_part = core
            prerelease_part = ''
            has_prerelease = False

        major_str, minor_str, patch_str = main_part.split('.')
        major, minor, patch = int(major_str), int(minor_str), int(patch_str)

        if has_prerelease:
            identifiers = prerelease_part.split('.')
            id_keys = []
            for ident in identifiers:
                if ident.isdigit():
                    id_keys.append((0, int(ident)))
                else:
                    id_keys.append((1, ident))
            no_prerelease_flag = 0
        else:
            id_keys = []
            no_prerelease_flag = 1

        return (major, minor, patch, no_prerelease_flag, tuple(id_keys))

    return sorted(versions, key=parse_key)

